export const MAX_EVALUATION_COMMAND_OUTPUT_LENGTH = 2_000;

const TRUNCATION_MARKER = '… [truncated]';

export function truncateText(value: string, maximumLength: number): string {
  if (value.length <= maximumLength) return value;
  if (maximumLength <= 0) return '';
  if (maximumLength <= TRUNCATION_MARKER.length) return value.slice(0, maximumLength);

  const contentLength = maximumLength - TRUNCATION_MARKER.length;
  return `${value.slice(0, contentLength)}${TRUNCATION_MARKER}`;
}

export function limitStrings(
  values: string[],
  maximumItems: number = MAX_EVALUATION_LIST_ITEMS,
  maximumLength: number = MAX_EVALUATION_TEXT_LENGTH,
): string[] {
  return values.slice(0, maximumItems).map((value) => truncateText(value, maximumLength));
}

export function requireBoundedTask(task: string): string {
  if (task.length > MAX_TASK_LENGTH) {
    throw new Error(`Task exceeds the ${MAX_TASK_LENGTH}-character limit.`);
  }
  return task;
}
/** Execution control is deliberately separate from serializable approved inputs. */
export type ExecutionOptions = { signal?: AbortSignal };

export type PromptStopReason = 'input_closed' | 'input_timeout' | 'input_cancelled';

/** A missing response must not become an approval, clarification, or signal. */
export class PromptStoppedError extends Error {
  constructor(readonly reason: PromptStopReason) {
    super(`Prompt stopped: ${reason}.`);
    this.name = 'PromptStoppedError';
  }
}

export class RunInterruptedError extends Error {
  constructor() {
    super('Run interrupted.');
    this.name = 'RunInterruptedError';
  }
}

export function throwIfInterrupted(signal?: AbortSignal): void {
  if (signal?.aborted) throw new RunInterruptedError();
}

/** Only use for boundaries that cannot edit the repository. Fence late continuations. */
export async function interruptible<T>(start: () => Promise<T>, signal?: AbortSignal): Promise<T> {
  throwIfInterrupted(signal);
  if (!signal) return start();
  return new Promise<T>((resolve, reject) => {
    const abort = (): void => reject(new RunInterruptedError());
    signal.addEventListener('abort', abort, { once: true });
    Promise.resolve().then(() => {
      throwIfInterrupted(signal);
      return start();
    }).then((value) => {
      throwIfInterrupted(signal);
      resolve(value);
    }).catch(reject).finally(() => signal.removeEventListener('abort', abort));
  });
}
