    root, packageManager: 'pnpm', scripts: ['verify', 'check', 'test', 'build'],
    validationScripts: ['verify', 'check', 'test', 'build'], requiredValidationScripts: ['check', 'test', 'build'],
    validationScriptCoverage: { verify: ['verify', 'check', 'test'] },
